import { BilingualText, PreferredLanguage } from "./types.ts";
import { getSupabaseAdminClient } from "./supabaseClient.ts";

const languageCache = new Map<string, { lang: PreferredLanguage; expireAt: number }>();

export function render(pair: BilingualText, prefLang: PreferredLanguage): string {
  if (prefLang === "en") {
    return pair.en;
  }
  if (prefLang === "zh") {
    return pair.zh;
  }
  return `${pair.zh}\n─────────────\n${pair.en}`;
}

export async function getUserPreferredLanguage(
  userId: string,
  lineProfileLanguage?: string,
  lineDisplayName?: string
): Promise<PreferredLanguage> {
  if (!userId || !userId.startsWith("U")) {
    return null;
  }

  const now = Date.now();
  const cached = languageCache.get(userId);
  if (cached && cached.expireAt > now) {
    return cached.lang;
  }

  try {
    const client = getSupabaseAdminClient();
    const { data: member } = await client
      .from("members")
      .select("preferred_language")
      .eq("line_user_id", userId)
      .maybeSingle();

    if (member && member.preferred_language) {
      const dbLang = String(member.preferred_language).toLowerCase();
      if (dbLang.startsWith("en")) {
        languageCache.set(userId, { lang: "en", expireAt: now + 300 * 1000 });
        return "en";
      }
      if (dbLang.startsWith("zh")) {
        languageCache.set(userId, { lang: "zh", expireAt: now + 300 * 1000 });
        return "zh";
      }
    }
  } catch (err) {
    console.warn(`Failed to fetch preferred_language from DB for ${userId}:`, err);
  }

  if (lineProfileLanguage) {
    const profileLang = lineProfileLanguage.toLowerCase();
    if (profileLang.startsWith("en")) {
      languageCache.set(userId, { lang: "en", expireAt: now + 300 * 1000 });
      return "en";
    }
    if (profileLang.startsWith("zh")) {
      languageCache.set(userId, { lang: "zh", expireAt: now + 300 * 1000 });
      return "zh";
    }
  }

  if (lineDisplayName) {
    const hasHan = /[\u4e00-\u9fa5]/.test(lineDisplayName);
    const hasLatin = /[a-zA-Z]/.test(lineDisplayName);
    if (!hasHan && hasLatin) {
      languageCache.set(userId, { lang: "en", expireAt: now + 300 * 1000 });
      return "en";
    }
    if (hasHan) {
      languageCache.set(userId, { lang: "zh", expireAt: now + 300 * 1000 });
      return "zh";
    }
  }

  languageCache.set(userId, { lang: null, expireAt: now + 300 * 1000 });
  return null;
}

const TAIPEI_TIMEZONE = "Asia/Taipei";

export function formatTaipeiDate(
  dateInput: string | number | Date,
  format = "YYYY-MM-DD"
): string {
  if (!dateInput) return "";

  const d = new Date(dateInput);
  if (isNaN(d.getTime())) return "";

  const formatter = new Intl.DateTimeFormat("en-US", {
    timeZone: TAIPEI_TIMEZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  });

  const parts = formatter.formatToParts(d);
  const map: Record<string, string> = {};
  for (const part of parts) {
    if (part.type !== "literal") {
      map[part.type] = part.value;
    }
  }

  const YYYY = map.year || "1970";
  const MM = map.month || "01";
  const DD = map.day || "01";
  const HH = map.hour || "00";
  const mm = map.minute || "00";
  const ss = map.second || "00";

  return format
    .replace("YYYY", YYYY)
    .replace("MM", MM)
    .replace("DD", DD)
    .replace("HH", HH)
    .replace("mm", mm)
    .replace("ss", ss);
}

export function parseTaipeiDate(dateStr: string): Date | null {
  if (!dateStr) return null;

  let cleaned = String(dateStr).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(cleaned)) {
    cleaned = `${cleaned}T23:59:59+08:00`;
  } else if (/^\d{4}\/\d{2}\/\d{2}$/.test(cleaned)) {
    cleaned = `${cleaned.replace(/\//g, "-")}T23:59:59+08:00`;
  } else if (cleaned.endsWith("23:59:59Z")) {
    cleaned = cleaned.replace(/23:59:59Z$/, "23:59:59+08:00");
  }

  const parsed = new Date(cleaned);
  return isNaN(parsed.getTime()) ? null : parsed;
}

export function isEventExpired(deadlineInput: string | Date | null | undefined): boolean {
  if (!deadlineInput) return false;

  let deadlineDate: Date | null = null;
  if (deadlineInput instanceof Date) {
    deadlineDate = deadlineInput;
  } else {
    deadlineDate = parseTaipeiDate(deadlineInput);
  }

  if (!deadlineDate || isNaN(deadlineDate.getTime())) {
    return false;
  }

  return Date.now() > deadlineDate.getTime();
}

export function formatEventDate(
  startDateStr: string | null | undefined,
  endDateStr: string | null | undefined
): string {
  if (!startDateStr && !endDateStr) return "日期未定 TBD";
  if (startDateStr && !endDateStr) return formatTaipeiDate(startDateStr, "YYYY/MM/DD");
  if (!startDateStr && endDateStr) return formatTaipeiDate(endDateStr, "YYYY/MM/DD");

  const startFormatted = formatTaipeiDate(startDateStr!, "YYYY/MM/DD");
  const endFormatted = formatTaipeiDate(endDateStr!, "YYYY/MM/DD");

  if (startFormatted === endFormatted) {
    return startFormatted;
  }
  return `${startFormatted} ~ ${endFormatted}`;
}

export function generateSignupId(): string {
  const now = new Date();
  const timestamp = formatTaipeiDate(now, "MMDDHHmmss");
  return `S${timestamp}`;
}

import { isEventExpired } from "./dateUtils.ts";
import { PreferredLanguage } from "./types.ts";

export function isEventFuture(status: string | null | undefined): boolean {
  if (!status) return false;
  const s = status.toLowerCase();
  return s.includes("未來") || s.includes("coming") || s.includes("future");
}

export function isEventClosed(status: string | null | undefined): boolean {
  if (!status) return false;
  const s = status.toLowerCase();
  return (
    s.includes("關閉") ||
    s.includes("closed") ||
    s.includes("draft") ||
    s.includes("草稿") ||
    s.includes("已截止") ||
    s.includes("已結束") ||
    s.includes("finished")
  );
}

export function isEventOpen(
  status: string | null | undefined,
  deadline: string | Date | null | undefined
): boolean {
  if (!status) return false;
  if (isEventFuture(status)) return false;
  if (isEventClosed(status)) return false;
  if (isEventExpired(deadline)) return false;

  const s = status.toLowerCase();
  return s.includes("開放") || s.includes("open") || s.includes("報名中");
}

export function isSignupCancelled(status: string | null | undefined): boolean {
  if (!status) return false;
  const s = status.toLowerCase();
  return s.includes("取消") || s.includes("cancel");
}

export function formatSignupStatus(
  status: string,
  prefLang: PreferredLanguage
): string {
  const map: Record<string, { zh: string; en: string }> = {
    "正取 Confirmed": { zh: "正取", en: "Confirmed" },
    "正取（已繳費）Confirmed (Paid)": { zh: "正取（已繳費）", en: "Confirmed (Paid)" },
    "備取 Waitlisted": { zh: "備取", en: "Waitlisted" },
    "備取（有意願）Waitlisted (Interested)": { zh: "備取（有意願）", en: "Waitlisted (Interested)" },
    "審核中 Checking": { zh: "審核中", en: "Checking" },
    "已取消 Cancelled": { zh: "已取消", en: "Cancelled" },
  };

  const found = map[status];
  if (!found) return status;

  if (prefLang === "zh") return found.zh;
  if (prefLang === "en") return found.en;
  return status;
}
